/// Look up a component by its full type name.
pub fn component(name: &str) -> Option<&'static ComponentInfo> {
    COMPONENTS
        .binary_search_by(|c| c.name.cmp(name))
        .ok()
        .map(|i| &COMPONENTS[i])
}
